// The committed eBay callback signature and ticket vectors — generator.
//
//   node functions/test/fixtures/generate-ebay-callback-vectors.mjs          verify
//   node functions/test/fixtures/generate-ebay-callback-vectors.mjs --force  rewrite
//
// Design §5.5, "The committed signature vectors — the skip ends here". §5.4
// planned `ebay-callback-signature-vectors.json` and it was never written,
// blocked on one question and not on effort: WHO MINTS THE FIXTURE KEY AND WHERE
// IS IT RECORDED? The answer this file implements is that the fixture mints its
// own key, inside itself, and says what it is on every line that matters. The
// key below is 32 random bytes with no meaning anywhere: it is not a secret, has
// never been one, is used by nothing outside `functions/test/**` and
// `studioflow-web/scripts/**`, and must never be set in Secret Manager or in
// Hostinger. `ebay-connect.test.js` asserts that last sentence by grepping the
// whole repository for the value.
//
// WHY A FIXTURE AT ALL, when `check-ebay-relay-vectors.mjs` already runs the two
// implementations against each other. Because that check is symmetric: it proves
// the route and the function agree, and it goes green just as happily if BOTH of
// them move together. There are now two canonical strings to keep still — the
// relay signature and the ticket — and a frozen answer is the only thing that
// notices a matched pair of edits.
//
// WHAT IS FROZEN AND WHAT IS DERIVED. The fixture's INPUTS (the two test keys,
// the clock, the state, the nonce, the code, the rids, the ticket's jti) are
// random once and then read back out of the committed file for ever. Every
// DERIVED value — every signature, every ticket — is recomputed here by the REAL
// implementation (`_internal.callbackDigest`, `_internal.mintTicket`) and
// compared with what is committed. So a re-run is a no-op unless a format
// changed, and if one did, this script says which value moved and refuses to
// overwrite it without `--force`. Nothing here re-implements either canonical
// string; a generator that wrote its own HMAC would freeze the generator's
// arithmetic instead of the connector's.
//
// The one thing stubbed is `crypto.randomBytes`, for the length the ticket
// minter uses for its `jti`, and only for the duration of one mint call. Without
// it the real minter cannot be asked for the same ticket twice, and the fixture
// could not be a fixture.
import { createRequire } from "node:module";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const require = createRequire(import.meta.url);
const crypto = require("node:crypto");
const { buildEbay } = require("../qa/helpers/ebayHarness.js");

const here = path.dirname(new URL(import.meta.url).pathname);
const fixturePath = path.join(here, "ebay-callback-signature-vectors.json");
const force = process.argv.includes("--force");

const KEY_LABEL = "TEST-KEY-NOT-A-SECRET";
const README = [
  "TEST VECTORS ONLY.",
  `The two keys below ("key" and "wrongKey") are TEST keys generated by`,
  "functions/test/fixtures/generate-ebay-callback-vectors.mjs for this file alone.",
  "Neither is a secret, neither has ever been a secret, neither has ever been used to sign anything real.",
  "They are used by nothing outside functions/test/** and studioflow-web/scripts/**,",
  "and they must NEVER be set in Google Secret Manager as EBAY_CALLBACK_KEY,",
  "nor in the Hostinger environment as NIVADESK_EBAY_CALLBACK_KEY.",
  "ebay-connect.test.js fails if either value appears in any other file in this repository."
].join(" ");

// A clock with no meaning either, but a FIXED one: a vector whose timestamp
// moved with the wall clock would not be a vector. Thirteen digits, because the
// ticket's own shape check requires exactly that many.
const BASE_NOW_MS = Date.parse("2026-09-06T12:00:00.000Z");
const SKEW_MS = 5 * 60 * 1000;          // the function's window, mirrored here as data
const OUTSIDE_MS = 6 * 60 * 1000;       // one minute past it, in both directions
// Inside the verifier's remaining-life bound (15 minutes) at every one of the
// three clocks above, so the same ticket serves the stale and future vectors.
const TICKET_LIFE_MS = 8 * 60 * 1000;

const existing = (() => {
  try { return JSON.parse(readFileSync(fixturePath, "utf8")); } catch { return null; }
})();
const seeded = existing !== null;
const seed = (pathParts, mint) => {
  let node = existing;
  for (const part of pathParts) node = node && typeof node === "object" ? node[part] : undefined;
  return node === undefined || node === null ? mint() : node;
};

// ---- the inputs: random once, read back for ever ----------------------------
const key = seed(["key"], () => crypto.randomBytes(32).toString("hex"));
const wrongKey = seed(["wrongKey"], () => crypto.randomBytes(32).toString("hex"));
const nowMs = seed(["clock", "nowMs"], () => BASE_NOW_MS);
const flow = {
  state: seed(["flow", "state"], () => crypto.randomBytes(32).toString("base64url")),
  nonce: seed(["flow", "nonce"], () => crypto.randomBytes(24).toString("base64url")),
  otherNonce: seed(["flow", "otherNonce"], () => crypto.randomBytes(24).toString("base64url")),
  otherState: seed(["flow", "otherState"], () => crypto.randomBytes(32).toString("base64url")),
  code: seed(["flow", "code"], () => "VECTORCODE-not-a-real-eBay-code"),
  swappedCode: seed(["flow", "swappedCode"], () => "VECTORCODE-swapped-under-a-signature-for-another-body"),
  connectRid: seed(["flow", "connectRid"], () => crypto.randomBytes(8).toString("hex")),
  disposeRid: seed(["flow", "disposeRid"], () => crypto.randomBytes(8).toString("hex")),
  ticketJti: seed(["flow", "ticketJti"], () => crypto.randomBytes(16).toString("base64url")),
  expiredTicketJti: seed(["flow", "expiredTicketJti"], () => crypto.randomBytes(16).toString("base64url"))
};

// ---- the real implementations, reached through the qa harness ---------------
const harness = buildEbay({ nowRef: { value: nowMs } });
const internal = harness.fns._internal;

/** The ticket minter, asked for the same ticket twice. See the header note. */
function mint(withKey, state, nonce, expMs, jti) {
  const realRandomBytes = crypto.randomBytes;
  const fixed = Buffer.from(jti, "base64url");
  crypto.randomBytes = (size) => (size === fixed.length ? Buffer.from(fixed) : realRandomBytes(size));
  harness.switches.callbackKey = withKey;
  try { return internal.mintTicket(state, nonce, expMs); } finally {
    crypto.randomBytes = realRandomBytes;
    harness.switches.callbackKey = key;
  }
}
const sign = (withKey, timestampMs, body) => internal.callbackDigest(withKey, String(timestampMs), Buffer.from(body, "utf8"));

// ---- the bodies, in the exact key order the route serialises -----------------
// `app/ebay/callback/route.ts` builds these two and nothing else. The order
// matters: a signature is over bytes, so a re-serialisation with a different key
// order is a different vector.
const connectBody = (code) => JSON.stringify({ v: 1, rid: flow.connectRid, code, state: flow.state, nonce: flow.nonce });
const disposeBody = JSON.stringify({ v: 1, op: "dispose", rid: flow.disposeRid, code: flow.code });
const validBody = connectBody(flow.code);

// ---- the five cases the ticket asked for, plus the dispose envelope ---------
// `routeReproduces` says one thing only: the WEB route, signing this vector's
// `signedBody` at this vector's `timestampMs` under the fixture key, emits this
// exact signature. It is true for every vector signed under the fixture key —
// including the swapped-body one, whose signature IS the valid signature; what
// makes that vector negative is that `body` is not `signedBody`. It is false
// only for the wrong-key vector, which the route cannot produce at all.
const relayVectors = [
  {
    id: "relay-connect-valid",
    name: "a valid signature: the connect envelope, signed under the fixture key at the fixture's own clock",
    envelope: "connect", keyUsed: "key", rid: flow.connectRid,
    timestampMs: nowMs, nowMs, body: validBody, signedBody: validBody,
    signature: sign(key, nowMs, validBody), expect: "ok", routeReproduces: true
  },
  {
    id: "relay-dispose-valid",
    name: "a valid signature over the OTHER envelope: dispose, which names no state and no nonce",
    envelope: "dispose", keyUsed: "key", rid: flow.disposeRid,
    timestampMs: nowMs, nowMs, body: disposeBody, signedBody: disposeBody,
    signature: sign(key, nowMs, disposeBody), expect: "ok", routeReproduces: true
  },
  {
    id: "relay-wrong-key",
    name: "a wrong key: the same bytes at the same moment, signed under the second test key",
    envelope: "connect", keyUsed: "wrongKey", rid: flow.connectRid,
    timestampMs: nowMs, nowMs, body: validBody, signedBody: validBody,
    signature: sign(wrongKey, nowMs, validBody), expect: "unsigned", routeReproduces: false
  },
  {
    id: "relay-swapped-body",
    name: "a swapped body: a signature valid for the body above, presented over a body whose code was changed",
    envelope: "connect", keyUsed: "key", rid: flow.connectRid,
    timestampMs: nowMs, nowMs, body: connectBody(flow.swappedCode), signedBody: validBody,
    signature: sign(key, nowMs, validBody), expect: "unsigned", routeReproduces: true
  },
  {
    id: "relay-stale-timestamp",
    name: "a stale timestamp: correctly signed six minutes in the past, one minute outside the window",
    envelope: "connect", keyUsed: "key", rid: flow.connectRid,
    timestampMs: nowMs - OUTSIDE_MS, nowMs, body: validBody, signedBody: validBody,
    signature: sign(key, nowMs - OUTSIDE_MS, validBody), expect: "skew", routeReproduces: true
  },
  {
    id: "relay-future-timestamp",
    name: "a future timestamp: correctly signed six minutes ahead — the window is absolute, not one-sided",
    envelope: "connect", keyUsed: "key", rid: flow.connectRid,
    timestampMs: nowMs + OUTSIDE_MS, nowMs, body: validBody, signedBody: validBody,
    signature: sign(key, nowMs + OUTSIDE_MS, validBody), expect: "skew", routeReproduces: true
  }
];

// ---- the ticket, the second canonical string §5.5 added ---------------------
const ticketExpMs = nowMs + TICKET_LIFE_MS;
const validTicket = mint(key, flow.state, flow.nonce, ticketExpMs, flow.ticketJti);
const wrongKeyTicket = mint(wrongKey, flow.state, flow.nonce, ticketExpMs, flow.ticketJti);
const expiredTicket = mint(key, flow.state, flow.nonce, nowMs - 1000, flow.expiredTicketJti);
// The MAC's last character flipped inside its own alphabet, so the SHAPE still
// passes and the failure is the MAC rather than the regex.
const bentTicket = `${validTicket.slice(0, -1)}${validTicket.endsWith("A") ? "B" : "A"}`;
const tag = (ticket) => String(ticket).split(".")[2];
const flowTag = flow.state.slice(0, 16);

const ticketVectors = [
  {
    id: "ticket-valid", name: "the ticket the real minter produces for this flow, byte for byte",
    keyUsed: "key", state: flow.state, nonce: flow.nonce, expMs: ticketExpMs, jti: flow.ticketJti,
    nonceTag: tag(validTicket), ticket: validTicket, verifyAtMs: nowMs, expect: "ok",
    cookieName: `__Host-nv_ebay_ticket_${flowTag}`, nonceCookieName: `__Host-nv_ebay_nonce_${flowTag}`,
    mintedByTheRealMinter: true
  },
  {
    id: "ticket-wrong-key", name: "the same fields minted under the second test key: the MAC does not verify here",
    keyUsed: "wrongKey", state: flow.state, nonce: flow.nonce, expMs: ticketExpMs, jti: flow.ticketJti,
    nonceTag: tag(wrongKeyTicket), ticket: wrongKeyTicket, verifyAtMs: nowMs, expect: "mac",
    cookieName: `__Host-nv_ebay_ticket_${flowTag}`, nonceCookieName: `__Host-nv_ebay_nonce_${flowTag}`,
    mintedByTheRealMinter: true
  },
  {
    id: "ticket-expired", name: "a correctly minted ticket whose window closed one second before the clock",
    keyUsed: "key", state: flow.state, nonce: flow.nonce, expMs: nowMs - 1000, jti: flow.expiredTicketJti,
    nonceTag: tag(expiredTicket), ticket: expiredTicket, verifyAtMs: nowMs, expect: "expired",
    cookieName: `__Host-nv_ebay_ticket_${flowTag}`, nonceCookieName: `__Host-nv_ebay_nonce_${flowTag}`,
    mintedByTheRealMinter: true
  },
  {
    id: "ticket-bent-mac", name: "the valid ticket with one character of its MAC changed: shape intact, MAC refused",
    keyUsed: "key", state: flow.state, nonce: flow.nonce, expMs: ticketExpMs, jti: flow.ticketJti,
    nonceTag: tag(validTicket), ticket: bentTicket, verifyAtMs: nowMs, expect: "mac",
    cookieName: `__Host-nv_ebay_ticket_${flowTag}`, nonceCookieName: `__Host-nv_ebay_nonce_${flowTag}`,
    mintedByTheRealMinter: false
  },
  {
    id: "ticket-other-state", name: "the valid ticket offered for a different flow's state",
    keyUsed: "key", state: flow.state, nonce: flow.nonce, expMs: ticketExpMs, jti: flow.ticketJti,
    nonceTag: tag(validTicket), ticket: validTicket, verifyAtMs: nowMs, expect: "state",
    queryState: flow.otherState,
    cookieName: `__Host-nv_ebay_ticket_${flowTag}`, nonceCookieName: `__Host-nv_ebay_nonce_${flowTag}`,
    mintedByTheRealMinter: false
  },
  {
    id: "ticket-other-nonce", name: "the valid ticket offered beside a different flow's nonce cookie",
    keyUsed: "key", state: flow.state, nonce: flow.nonce, expMs: ticketExpMs, jti: flow.ticketJti,
    nonceTag: tag(validTicket), ticket: validTicket, verifyAtMs: nowMs, expect: "nonce",
    nonceOffered: flow.otherNonce,
    cookieName: `__Host-nv_ebay_ticket_${flowTag}`, nonceCookieName: `__Host-nv_ebay_nonce_${flowTag}`,
    mintedByTheRealMinter: false
  }
];

const built = {
  README,
  keyLabel: KEY_LABEL,
  generatedBy: "functions/test/fixtures/generate-ebay-callback-vectors.mjs",
  consumedBy: [
    "functions/test/qa/ebay-connect.test.js",
    "studioflow-web/scripts/check-ebay-relay-vectors.mjs"
  ],
  canonical: {
    relaySignature: "HMAC-SHA256(key, \"v1.\" + timestampMs + \".\" + rawBodyBytes), lowercase hex, sent as x-nivadesk-signature: v1=<hex>",
    ticketKey: "HMAC-SHA256(key, \"nivadesk/ebay/ticket/v1\") — derived, so there is no sixth secret",
    nonceTag: "base64url(HMAC-SHA256(ticketKey, \"nonce.\" + nonce))",
    ticket: "nv1.<state>.<nonceTag>.<expMs>.<jti>.<base64url(HMAC-SHA256(ticketKey, everything before the last dot))>",
    cookieName: "__Host-nv_ebay_ticket_<first 16 characters of the state>"
  },
  key,
  wrongKey,
  clock: { nowMs, skewMs: SKEW_MS, outsideMs: OUTSIDE_MS },
  flow: { ...flow, ticketExpMs, flowTag },
  relayVectors,
  ticketVectors
};

const serialised = `${JSON.stringify(built, null, 2)}\n`;

if (!seeded) {
  writeFileSync(fixturePath, serialised);
  console.log(`WROTE ${fixturePath} — first run, ${relayVectors.length} relay vectors and ${ticketVectors.length} ticket vectors under a new test key.`);
  process.exit(0);
}

// ---- a re-run is a verification, not a rewrite ------------------------------
const drift = [];
const compare = (label, was, is) => { if (JSON.stringify(was) !== JSON.stringify(is)) drift.push(`${label}: committed ${JSON.stringify(was)} ≠ regenerated ${JSON.stringify(is)}`); };
for (const vector of relayVectors) {
  const was = (existing.relayVectors || []).find((v) => v.id === vector.id);
  if (!was) { drift.push(`${vector.id}: absent from the committed fixture`); continue; }
  compare(`${vector.id}.body`, was.body, vector.body);
  compare(`${vector.id}.signature`, was.signature, vector.signature);
  compare(`${vector.id}.timestampMs`, was.timestampMs, vector.timestampMs);
}
for (const vector of ticketVectors) {
  const was = (existing.ticketVectors || []).find((v) => v.id === vector.id);
  if (!was) { drift.push(`${vector.id}: absent from the committed fixture`); continue; }
  compare(`${vector.id}.ticket`, was.ticket, vector.ticket);
  compare(`${vector.id}.nonceTag`, was.nonceTag, vector.nonceTag);
  compare(`${vector.id}.cookieName`, was.cookieName, vector.cookieName);
}

// `--force` rewrites whatever it finds, drift or none: it is how a deliberate
// format change and a shape change to the fixture itself both land. The diff is
// the change to review, which is the whole reason the file is committed.
if (force) {
  writeFileSync(fixturePath, serialised);
  console.log(`FORCED ${fixturePath} rewritten${drift.length ? ` over ${drift.length} drifted value(s)` : " with no drift in the derived values"}.`);
  for (const line of drift) console.log(`       ${line}`);
  process.exit(0);
}

if (!drift.length) {
  console.log(`OK    ${fixturePath} — every derived value regenerates identically from the real implementations.`);
  process.exit(0);
}

console.log("DRIFT the committed vectors no longer match what the real implementations produce:");
for (const line of drift) console.log(`      ${line}`);
console.log("");
console.log("      This is the alarm the fixture exists to raise. A canonical string moved on the FUNCTION side.");
console.log("      If that change was intended, re-run with --force, and expect the committed diff to be read.");
process.exit(1);
